Lemma huf_rdt_x2_proof : huf_rdt_stmt huf_dt_ok PHUF_RDT_X2.
Proof.
  intros ra sp gp tp t0 t1 t2 s0 s1 a0 a1 a2 a3 a4 a5 a6 a7 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 t3 t4 t5 t6 F fc m DT W S mtl flags src jdt jw lo
    MTL RDT RW SRC SRCB SRCN S16 DT0 DTA W0 WA S0 DTL WL SL DJ1 DJ2 DJ3 ST LOS SPA SPB MI FL HA0 HA1 HA2 HA3 HA4 HA5.
  subst a0 a1 a2 a3 a4 a5.
  pose proof (munch_refl [(bv_unsigned sp - HUF_RDT_STACK, bv_unsigned sp); (DT, DT + DTABLE_BYTES mtl); (W, W + 8704)] m) as MU.
  pose proof (wmono_refl usegs m) as WM.
  unfold PHUF_RDT_X2. unfold HUF_RDT_STACK, DTABLE_BYTES, HufHarness.DT_BYTES in *.
  assert (P2 : 2 <= 2^mtl <= 4096) by (split; [change 2 with (2^1); apply Z.pow_le_mono_r; lia | change 4096 with (2^12); apply Z.pow_le_mono_r; lia]).
  pose proof (rw_cells_CB_length usegs _ _ _ _ RW) as LJW0.
  assert (LJW : zlen jw = 8704) by (rewrite LJW0; reflexivity). clear LJW0.
  apply (u8arr_of_rw_cells usegs) in RW.
  apply (proj1 (rw_cells_app' usegs m DT [C4 _] [CB _ jdt])) in RDT. destruct RDT as [RDT RDJ]. cbn [cells_size csize Nat.add Z.of_nat] in RDJ.
  pose proof (rw_cells_CB_length usegs _ _ _ _ RDJ) as LJD.
  apply (u8arr_of_rw_cells usegs) in RDJ.
  assert (WA4 : Z.land W 3 = 0) by (change 3 with (Z.ones 2); rewrite Z.land_ones by lia; Z.div_mod_to_equations; lia).
  assert (DTA4 : Z.land DT 3 = 0) by (change 3 with (Z.ones 2); rewrite Z.land_ones by lia; Z.div_mod_to_equations; lia).
  pose proof (x2k_mtl_byte mtl MTL) as MTB. pose proof (x2k_mtl_byte' mtl MTL) as MTB'.
  carve_frame 400%nat ST.
  pose proof (x2k_u8sub _ _ _ 0 624 RW ltac:(lia) ltac:(lia) ltac:(lia)) as RVa. rewrite Z.add_0_r in RVa.
  pose proof (x2k_u8sub _ _ _ 624 112 RW ltac:(lia) ltac:(lia) ltac:(lia)) as MSa.
  pose proof (x2k_u8sub _ _ _ 736 256 RW ltac:(lia) ltac:(lia) ltac:(lia)) as SYa.
  pose proof (x2k_u8sub _ _ _ 992 256 RW ltac:(lia) ltac:(lia) ltac:(lia)) as HWa.
  pose proof (x2k_u8sub _ _ _ 1248 876 RW ltac:(lia) ltac:(lia) ltac:(lia)) as STa.
  pose proof (x2k_sub_len jw 0 624 ltac:(lia) ltac:(lia) ltac:(lia)) as LRV. pose proof (x2k_sub_len jw 624 112 ltac:(lia) ltac:(lia) ltac:(lia)) as LMS.
  pose proof (x2k_sub_len jw 736 256 ltac:(lia) ltac:(lia) ltac:(lia)) as LSY. pose proof (x2k_sub_len jw 992 256 ltac:(lia) ltac:(lia) ltac:(lia)) as LHW.
  pose proof (x2k_sub_len jw 1248 876 ltac:(lia) ltac:(lia) ltac:(lia)) as LST.
  set (jrv := firstn (Z.to_nat 624) (skipn (Z.to_nat 0) jw)) in *. set (jms := firstn (Z.to_nat 112) (skipn (Z.to_nat 624) jw)) in *.
  set (jsy := firstn (Z.to_nat 256) (skipn (Z.to_nat 736) jw)) in *. set (jhw := firstn (Z.to_nat 256) (skipn (Z.to_nat 992) jw)) in *.
  set (jst := firstn (Z.to_nat 876) (skipn (Z.to_nat 1248) jw)) in *. clearbody jrv jms jsy jhw jst. clear RW.
  apply (rw_cells_of_u8arr usegs) in MSa. rewrite LMS in MSa.
  assert (LSRCM : Z.of_nat (length (map (Z_to_bv 8) src)) = zlen src) by (rewrite length_map; reflexivity).
  x2upto 168. zstep.
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    eapply evt_cut;
    [ eapply (rd_memset_specZ (W + 624) 112 0); [exact MSa | exact MI | reflexivity | reflexivity | reflexivity | lia | lia | lia]
    | intros ms' PO; unfold rd_memsetZ_post in PO; revert ms' PO; post_call usegs mm ] end.
  x2upto 236. zstep.
  match goal with H : rw_cells usegs _ (W + 624) [CB _ _] |- _ => rename H into ZR end.
  apply (rw_cells_split_CB usegs _ _ [] _ _ [] [52; 60]%nat) in ZR; [|reflexivity]. cbn [mk_CB_cells app] in ZR.
  apply (proj1 (rw_cells_app' usegs _ _ [_] [_])) in ZR. destruct ZR as [ZRK ZRS]. cbn [cells_size csize Nat.add] in ZRS.
  replace (W + 624 + Z.of_nat 52) with (W + 676) in ZRS by lia.
  apply (u8arr_of_rw_cells usegs) in ZRK.
  assert (LZRK : zlen (firstn 52 (repeat (Z_to_bv 8 0) (Z.to_nat 112))) = 52) by (rewrite length_firstn, repeat_length; reflexivity).
  match goal with H : rw_cells usegs _ (bv_unsigned sp + -400) _ |- _ => rename H into FR end.
  apply (rw_cells_split_CB usegs _ _ [_; _; _; _; _; _] _ _ _ [152; 4; 4]%nat) in FR; [|reflexivity]. cbn [mk_CB_cells app] in FR.
  apply (proj1 (rw_cells_app' usegs _ _ [_; _; _; _; _; _; _] _)) in FR. destruct FR as [FRa FR].
  apply (proj1 (rw_cells_app' usegs _ _ [_] _)) in FR. destruct FR as [NSPc FR].
  apply (proj1 (rw_cells_app' usegs _ _ [_] _)) in FR. destruct FR as [TLPc FRb].
  cbn [cells_size csize Nat.add] in NSPc, TLPc, FRb.
  replace (bv_unsigned sp + -400 + Z.of_nat 288) with (bv_unsigned sp + -112) in NSPc by lia.
  replace (bv_unsigned sp + -400 + Z.of_nat 288 + Z.of_nat 4) with (bv_unsigned sp + -108) in TLPc by lia.
  replace (bv_unsigned sp + -400 + Z.of_nat 288 + Z.of_nat 4 + Z.of_nat 4) with (bv_unsigned sp + -104) in FRb by lia.
  apply rw_cells_cb4_c4 in NSPc. apply rw_cells_cb4_c4 in TLPc.
  assert (WNS : wr_at usegs _ (bv_unsigned sp + -112) 4) by exact (proj2 NSPc).
  assert (WTL : wr_at usegs _ (bv_unsigned sp + -108) 4) by exact (proj2 TLPc).
  pose proof (x2k_rw_cells_nth _ _ _ _ 0 (C1 (Z_to_bv 8 0)) FRa ltac:(cbn; lia)) as STK. cbn in STK. rewrite Z.add_0_r in STK.
  lazymatch goal with |- evt _ _ (MS _ _ _ _ _ ?mm _) =>
    eapply evt_cut;
    [ eapply huf_rstats_proof with (HW := W + 992) (RK := W + 624) (NSP := bv_unsigned sp + -112) (TLP := bv_unsigned sp + -108)
        (S := S) (W := W + 1248) (src := src) (jh := jhw) (jr := firstn 52 (repeat (Z_to_bv 8 0) (Z.to_nat 112))) (jw := jst) (lo := lo);
      rewrite ?unsigned_lit by lia; unfold HUF_RSTATS_STACK;
      first [ eassumption | reflexivity | lia | (f_equal; lia) | (apply bv_eq; rewrite !unsigned_lit by lia; lia) ]
    | intros ms' PO; unfold huf_rstats_post, HUF_RSTATS_STACK in PO; rewrite !unsigned_lit in PO by lia; revert ms' PO;
      post_call usegs mm ] end.
  match goal with H : stk _ _ lo _ |- _ => rename H into ST end.
  match goal with H : match read_stats src with _ => _ end |- _ => rename H into POST end.
  destruct (read_stats src) as [h|e| |] eqn:RS.
  3,4: contradiction.
  2: { destruct POST as (RET & E0). subst.
       pose proof (stk_of_rw_cells usegs _ _ _ FRa) as S1. cbn [cells_size csize Nat.add] in S1.
       pose proof (stk_of_wr_at _ _ _ WNS) as S2. pose proof (stk_of_wr_at _ _ _ WTL) as S3.
       pose proof (stk_merge usegs _ _ _ _ ST S1 ltac:(lia)) as S4.
       replace (bv_unsigned sp + -400 + Z.of_nat 288) with (bv_unsigned sp + -112) in S4 by lia.
       pose proof (stk_merge usegs _ _ _ _ S4 S2 ltac:(lia)) as S5.
       replace (bv_unsigned sp + -112 + 4) with (bv_unsigned sp + -108) in S5 by lia.
       pose proof (stk_merge usegs _ _ _ _ S5 S3 ltac:(lia)) as S6.
       replace (bv_unsigned sp + -108 + 4) with (bv_unsigned sp + -104) in S6 by lia.
       x2upto 2036. x2norm. try x2mk.
       eapply evt_eq; [ | eapply x2_epi ]; [ x2st | .. ]; first [ eassumption | lia | (intros; lia) ]. }
  destruct POST as (RET & (jrest & HWr & LJR) & RKr & NSr & TLr). subst.
  rewrite ?MTB, ?MTB' in FRa.
  apply (u8arr_of_rw_cells usegs) in ZRS.
  replace (firstn 60 (skipn 52 (repeat (Z_to_bv 8 0) (Z.to_nat 112)))) with (u32s (map (Z_to_bv 64) (repeat 0 15))) in ZRS
    by reflexivity.
  apply (proj2 (u32arr_u8arr _ _ _)) in ZRS.
  try x2mk.
  eapply evt_eq; [ | eapply x2_p1 ]; [ x2st | .. ].
  all: first [ eassumption | lia | reflexivity ].
Qed.
